nextflow_process {

    name "Test Process CELLPOSE on GPU"
    script "../main.nf"
    process "CELLPOSE"

    tag "modules"
    tag "modules_nfcore"
    tag "cellpose"
    tag "gpu"

    test("cellpose - gpu - with flows, no model") {

        when {
            config "./nextflow.config"
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'imaging/segmentation/cycif_tonsil_registered.ome.tif', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            def mask_files = process.out.mask[0][1].collect { file(it) }
            assertAll (
                { assert process.success },
                { assert mask_files.size() == 3 },
                { assert snapshot(mask_files.collect { it.name }).match("mask_files") },
                { assert mask_files.every { it.size() > 0 } },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith('versions') }).match("versions") }
            )
        }

    }

    test("cellpose - gpu - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'imaging/segmentation/cycif_tonsil_registered.ome.tif', checkIfExists: true)
                ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

